const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}};
let records=read(KEY,[]),books=read(BOOKS,[]),prefs={theme:'cinnabar',font:14,showShensha:true,hiddenShensha:[],ageMode:'virtual',hiddenOrder:'qi',hideRelations:[],...read(PREF,{})};
if(!Array.isArray(prefs.hiddenShensha))prefs.hiddenShensha=[];if(!Array.isArray(prefs.hideRelations))prefs.hideRelations=[];
if(!Array.isArray(records))records=[];if(!Array.isArray(books))books=[];
