const today=nowInput(defaults);
const state={tab:'bazi',current:initial,result:calculate(initial),decade:1,year:0,note:'',feedback:'',commentary:'',multiInputs:[],archiveCategory:'all',recordId:null,recordTags:'',query:'',knowledgeType:'all',partner:{...defaults,name:'乙方',date:'1992-09-18',gender:0},compare:null,flowDate:today.date,flowTime:'12:00',ziweiScope:'origin',palace:11,baziMode:'professional',calendarDate:today.date,termYear:+today.date.slice(0,4),wuyunYear:+today.date.slice(0,4),reverse:[],reverseValues:null,archiveQuery:'',onlyStar:false,readerId:null,readerPage:0,readerQuery:'',regionQuery:''};
const tabs=[['home','工作台'],['bazi','四柱八字'],['ziwei','紫微斗数'],['qimen','奇门遁甲'],['compare','双人合盘'],['multi','多盘对比'],['wealth','财星研习'],['calendar','万年历'],['wuyun','五运六气'],['reverse','四柱反查'],['records','研习档案'],['knowledge','知识库'],['reader','本地书房'],['rules','规则与显示']];
const navGroups=[['总览',['home']],['专业排盘',['bazi','ziwei','qimen']],['研习工具',['compare','multi','wealth','calendar','wuyun','reverse']],['资料管理',['records','knowledge','reader']],['偏好',['rules']]];
const iconPaths={home:'M3 11 12 3 21 11M5 10v11h5v-7h4v7h5V10',bazi:'M4 4h16v16H4zM4 9h16M9 4v16M15 4v16',ziwei:'M12 3v3m0 12v3M3 12h3m12 0h3M6 6l2 2m8 8 2 2M6 18l2-2m8-8 2-2M12 8l4 4-4 4-4-4z',qimen:'M4 4h16v16H4zM4 9h16M4 15h16M9 4v16M15 4v16',compare:'M4 5h6v14H4zM14 5h6v14h-6z',multi:'M3 4h7v7H3zM14 4h7v7h-7zM3 15h7v6H3zM14 15h7v6h-7z',wealth:'M4 19h16M6 15l4-5 4 3 5-8M15 5h4v4',calendar:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4M8 14h2m4 0h2m-8 3h2',records:'M4 5h6l2 3h8v12H4z',reader:'M3 5c4-2 6-1 9 1 3-2 5-3 9-1v14c-4-2-6-1-9 1-3-2-5-3-9-1zM12 6v14',rules:'M4 7h16M4 17h16M8 4v6m8 4v6',knowledge:'M12 3 3 8l9 5 9-5zM5 12v5l7 4 7-4v-5',reverse:'M4 8h13l-4-4M20 16H7l4 4',wuyun:'M3 9h12a3 3 0 1 0-3-3M3 13h16a3 3 0 1 1-3 3M3 17h6'};
const icon=(id)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[id]||iconPaths.bazi}"/></svg>`;

const colors={'木':'wood','火':'fire','土':'earth','金':'metal','水':'water'};
const char=(c,e)=>`<span class="${colors[e]||''}">${esc(c)}</span>`;
const selectOptions=(items,value)=>items.map(([v,label])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const choice=(name,label,items,value)=>`<label>${label}<select name="${name}">${selectOptions(items,value)}</select></label>`;
let offlineLabel=location.protocol==='file:'?'本地资源已内置':'正在准备离线缓存';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function store(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('本机存储空间不足，请导出备份后整理资料。');return false;}}
function persist(){return store(KEY,records);}
function applyPrefs(){document.documentElement.dataset.theme=prefs.theme;document.documentElement.style.setProperty('--font-size',prefs.font+'px');}
function formFields(i,partner=false){const id=partner?'p-':'';return `
 <label>姓名 / 命盘名称<input id="${id}name" name="name" maxlength="60" value="${esc(i.name)}"></label>
 <label>公历日期<input id="${id}date" name="date" type="date" min="1901-01-01" max="2099-12-31" required value="${esc(i.date)}"></label>
 <div class="form-pair"><label>出生时间<input id="${id}time" name="time" type="time" required value="${esc(i.time)}"></label>${choice('gender','性别',[[1,'男命'],[0,'女命']],i.gender)}</div>
 ${partner?'':`<div class="inline-actions"><button type="button" class="text-button" data-action="lunar">农历输入</button><button type="button" class="text-button" data-action="now">此刻</button></div>
 <label>出生地区<button type="button" class="place-picker" data-action="regions">${esc(i.place||'手动经度')} <span>选择 ›</span></button></label>
 <details class="settings"><summary>时间与排盘设置</summary><div class="settings-body">
 <label>标准时区 UTC 偏移<input name="utcOffset" type="number" step="0.25" min="-12" max="14" value="${esc(i.utcOffset??8)}"></label>
 <label>出生地经度<input name="longitude" type="number" min="-180" max="180" step="0.0001" value="${esc(i.longitude)}"></label>
 <label class="check"><input type="checkbox" name="trueSolar" ${i.trueSolar?'checked':''}>真太阳时（近似）</label>
 <label class="check"><input type="checkbox" name="dst" ${i.dst?'checked':''}>输入含夏令时（减 1 小时）</label>
 ${choice('yearBoundary','年柱交接', [['exact','立春交节时刻'],['lichunDay','立春当日零点（UTC+8）'],['springFestival','农历正月初一（UTC+8）']],i.yearBoundary||'exact')}
 ${choice('palaceMethod','命宫月序', [['jie','按节换月'],['qi','过中气按下月']],i.palaceMethod||'jie')}
 <label class="check"><input type="checkbox" name="minutePillar" ${i.minutePillar?'checked':''}>分柱：时上五鼠遁</label>
 ${choice('sect','子时换日',[[2,'零点换日'],[1,'23 点换日']],i.sect)}
 ${choice('yunSect','起运换算法',[[2,'按分钟换算'],[1,'按时辰换算']],i.yunSect)}
 ${choice('decadeCount','大运显示',[[12,'120 年'],[8,'80 年']],i.decadeCount)}
 ${choice('structureMethod','月令取格', [['透干','月令藏干透干优先'],['本气','月令本气直接取格']],i.structureMethod)}
 ${choice('ziweiAlgorithm','紫微安星', [['default','通行安星'],['zhongzhou','中州安星']],i.ziweiAlgorithm)}
 ${choice('ziweiType','紫微盘式', [['heaven','天盘'],['earth','地盘（中州）'],['human','人盘（中州）']],i.ziweiType)}
 ${choice('ziweiYearDivide','紫微年界', [['normal','正月初一'],['exact','立春']],i.ziweiYearDivide)}
 <label class="check"><input type="checkbox" name="fixLeap" ${i.fixLeap?'checked':''}>紫微闰月过半按下月</label>
 ${choice('qimenMethod','奇门定局',[['拆補','拆补'],['置闰','置闰（符头法）'],['手动','手动定局']],['符頭','符头'].includes(i.qimenMethod)?'置闰':i.qimenMethod)}
 <div class="form-pair">${choice('qimenYinYang','阴阳遁',[['陽','阳遁'],['陰','阴遁']],i.qimenYinYang)}${choice('qimenJu','手动局数',Array.from({length:9},(_,n)=>[n+1,(n+1)+' 局']),i.qimenJu)}</div>
 <p class="fine">时区填当地标准时，夏令时单独勾选。年、月柱以对应的实际节气时刻判断；日、时柱使用当地钟时或真太阳时。</p></div></details>`}`;}
function readForm(form){const f=new FormData(form),get=(k,fallback)=>f.get(k)??fallback;
 return {...state.current,name:String(get('name','未命名')).trim().slice(0,60)||'未命名',date:String(f.get('date')),time:String(f.get('time')),gender:+f.get('gender'),sect:+get('sect',2),yearBoundary:get('yearBoundary','exact'),palaceMethod:get('palaceMethod','jie'),minutePillar:f.has('minutePillar'),utcOffset:+get('utcOffset',8),longitude:+get('longitude',120),trueSolar:f.has('trueSolar'),dst:f.has('dst'),fixLeap:f.has('fixLeap'),yunSect:+get('yunSect',2),decadeCount:+get('decadeCount',12),structureMethod:get('structureMethod','透干'),ziweiAlgorithm:get('ziweiAlgorithm','default'),ziweiYearDivide:get('ziweiYearDivide','normal'),ziweiType:get('ziweiType','heaven'),qimenMethod:get('qimenMethod','拆補'),qimenJu:+get('qimenJu',1),qimenYinYang:get('qimenYinYang','陽')};
}
function updateInput(input,remount=true){const result=calculate(input);state.current=input;state.result=result;state.decade=1;state.year=0;state.recordId=null;state.note='';state.feedback='';state.commentary='';state.recordTags='';state.compare=null;store(OPTIONS,input);remount?mount():render();}
function mount(){applyPrefs();$('#app').innerHTML=`
 <header class="topbar"><a class="brand" href="#"><span class="brand-mark">历</span><span>星历 <small>离线研习室 <em>0.4.1</em></small></span></a><div class="top-meta"><span class="offline-dot"></span><span id="offline-status">${offlineLabel}</span><button class="top-icon" data-action="preferences">${icon('rules')}<span>显示</span></button><button class="top-icon" data-action="about">说明</button></div></header>
 <div class="workspace"><nav class="navigation" aria-label="功能模块"><button class="primary new-chart" data-action="edit-input">＋ 编辑 / 新建排盘</button>${navGroups.map(([name,ids])=>`<div class="nav-group"><small>${name}</small>${ids.map(id=>`<button data-tab="${id}" class="${state.tab===id?'active':''}">${icon(id)}<span>${tabs.find(t=>t[0]===id)[1]}</span></button>`).join('')}</div>`).join('')}<div class="nav-footer"><span class="offline-dot"></span>本机计算 · 本机保存<small>重要资料请定期备份</small></div></nav>
 <main><div class="contextbar"><div><span class="avatar">${esc(state.current.name.slice(0,1))}</span><div><b>${esc(state.current.name)}</b><span>${esc(state.current.date)} ${esc(state.current.time)} · ${+state.current.gender===1?'乾造':'坤造'} · ${esc(state.current.place)}</span></div></div><div class="context-actions"><button data-shift="-120" aria-label="前一时辰">‹</button><button data-action="edit-input">编辑出生资料</button><button data-shift="120" aria-label="后一时辰">›</button></div></div><section id="content" aria-live="polite"></section></main></div>
 <dialog id="input-dialog" class="input-dialog"><aside class="sidebar"><div class="side-heading"><h2>出生资料</h2><button data-action="close-input" aria-label="关闭出生资料">×</button></div><p class="fine">公历 / 农历 · 1901—2099</p><form id="chart-form">${formFields(state.current)}<button class="primary full" type="submit">计算并打开命盘</button></form><div class="quick-shift"><button data-shift="-1440">前一天</button><button data-shift="1440">后一天</button></div></aside></dialog>
 <dialog id="detail-dialog"><button class="dialog-close" data-action="close-dialog" aria-label="关闭">×</button><div id="dialog-body"></div></dialog><div id="toast" role="status"></div><input id="import-file" type="file" accept="application/json,.json" hidden><input id="book-file" type="file" accept="text/plain,.txt,.md" hidden>`;
 $('#chart-form').addEventListener('submit',e=>{e.preventDefault();try{state.tab=['home','rules','records'].includes(state.tab)?'bazi':state.tab;updateInput(readForm(e.target));toast('已完成本机排盘');}catch(err){toast(err.message);}});
 $('#input-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
 $('#import-file').addEventListener('change',importRecords);$('#book-file').addEventListener('change',importBook);render();window.scrollTo(0,0);}

function heading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><small class="eyebrow">${esc(kicker||'XINGLI / '+(state.tab==='bazi'?'BAZI':state.tab.toUpperCase()))}</small><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${actions}</div></div>`;}
const saveActions=()=>`<button class="secondary" data-action="print">打印 / PDF</button><button class="primary" data-action="save">${state.recordId?'更新档案':'存入档案'}</button>`;
const utcLabel=i=>`UTC${Number(i.utcOffset??8)>=0?'+':''}${i.utcOffset??8}`;
function summary(){const r=state.result,i=state.current;return `<div class="chart-caption"><b>${esc(i.name)}　${+i.gender===1?'乾造':'坤造'}</b><span>公历 ${esc(i.date)} ${esc(i.time)}（${utcLabel(i)}${i.dst?' 夏令时':''}）</span><span>农历 ${esc(r.lunar)}　${esc(i.place||'')}</span>${i.trueSolar?`<span>真太阳时 ≈ ${esc(r.date)} ${esc(r.time)}　校正 ${r.correction.toFixed(1)} 分钟</span>`:''}</div>`;}
function pillarTable(result,extra=[]){const cols=[...result.pillars,...extra],rows=[['主星',p=>esc(p.god)],['天干',p=>`<b class="big-char">${char(p.gan,p.elements[0])}</b>`],['地支',p=>`<b class="big-char">${char(p.zhi,p.elements[1])}</b>`],['藏干',p=>[...p.hidden].sort((a,b)=>prefs.hiddenOrder==='qi'?HIDDEN_QI_ORDER[p.zhi].indexOf(a.gan)-HIDDEN_QI_ORDER[p.zhi].indexOf(b.gan):0).map(h=>`${h.gan}<small>${h.god}</small>`).join('　')],['星运',p=>p.phase],['自坐',p=>p.selfPhase],['纳音',p=>p.nayin],['空亡',p=>p.void]];return `<div class="table-scroll"><table class="professional-table"><thead><tr><th>四柱</th>${cols.map(p=>`<th class="${extra.includes(p)?'flow-col':''}">${esc(p.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th>${label}</th>${cols.map(p=>`<td class="${extra.includes(p)?'flow-col':''}">${fn(p)}</td>`).join('')}</tr>`).join('')}${prefs.showShensha?`<tr class="shensha-row"><th>神煞</th>${cols.map(p=>`<td>${[...new Set((extra.includes(p)?shenshaForFlow():result.shensha).filter(h=>h.target===p.label&&!prefs.hiddenShensha.includes(h.name)).map(h=>h.name))].map(n=>`<button class="rule-chip" data-shensha="${esc(n)}">${esc(n)}</button>`).join('')||'—'}</td>`).join('')}</tr>`:''}</tbody></table></div>`;}
let flowCache=null;
function getFlow(){const key=JSON.stringify([state.current,state.flowDate,state.flowTime]);if(flowCache?.key!==key)flowCache={key,value:flowPillars(state.current,state.flowDate,state.flowTime)};return flowCache.value;}
function shenshaForFlow(){return getFlow().shensha;}
function flowControls(){return `<div class="flow-controls"><b>行运时刻 · ${utcLabel(state.current)}</b><input type="date" id="flow-date" min="1901-01-01" max="2099-12-31" value="${state.flowDate}" aria-label="行运日期"><input type="time" id="flow-time" value="${state.flowTime}" aria-label="行运时间"><button class="secondary" data-action="flow-now">今日</button></div>`;}
function relationsHTML(items){items=items.filter(x=>!prefs.hideRelations.includes(x.type));return `<div class="relation-list">${items.map(x=>`<div><span class="tag">${esc(x.type)}</span><p>${esc(x.text)}</p></div>`).join('')||'<p class="muted">未命中当前规则。</p>'}</div>`;}
function elementsCard(r){return `<section class="card"><div class="section-title"><h2>五行分布</h2><small>表层八字计数</small></div><div class="element-counts">${ELEMENTS.map(e=>`<span class="${colors[e]}">${e} <b>${r.counts[e]}</b></span>`).join('')}</div><p class="fine">四干＋四支本气，每字计 1；数量不作为旺衰评分。</p></section>`;}
function yunCard(){const r=state.result,d=r.decades[state.decade]||r.decades[1],years=d.years,y=years[state.year]||years[0];return `<section class="card"><div class="section-title"><h2>大运 / 小运 / 流年 / 流月</h2><small>${r.yun.forward?'顺排':'逆排'} · ${r.yun.years}年${r.yun.months}月${r.yun.days}天起运</small></div><p class="fine">起运：${esc(r.yun.start)}（UTC+8）　${prefs.ageMode==='full'?'周岁按公历生日；年份列全年范围':'年龄按虚岁列示'}</p><div class="decades">${r.decades.map((d,i)=>`<button data-decade="${i}" class="${i===state.decade?'selected':''}"><small>${d.startYear}</small><b>${esc(d.value)}</b><span>${prefs.ageMode==='full'?ageInYear(state.current.date,d.startYear)+'起':d.startAge+'—'+d.endAge+'岁'}</span></button>`).join('')}</div><div class="years">${years.map((y,i)=>`<button class="${i===state.year?'selected':''}" data-year="${i}"><small>${y.year} · ${prefs.ageMode==='full'?ageInYear(state.current.date,y.year):y.age+'岁'}</small><b>${y.value}</b><span>小运 ${esc(y.small)}</span></button>`).join('')}</div>${y?`<div class="months">${y.months.map(m=>`<button data-flow-month="${m.index}" data-flow-year="${y.year}"><small>${m.index+1}月</small><b>${m.value}</b></button>`).join('')}</div>`:''}</section>`;}
function baziView(){const r=state.result,f=state.baziMode==='flow'?getFlow():null;return heading('','四柱八字','专业细盘 · 点击神煞查看命中依据',saveActions())+`<div class="subnav">${[['professional','专业盘'],['flow','岁运同参'],['reading','综合解读']].map(([id,t])=>`<button data-bazi-mode="${id}" class="${state.baziMode===id?'selected':''}">${t}</button>`).join('')}</div>${f||state.baziMode==='reading'?flowControls():''}${baziChart(f)}${state.baziMode==='reading'?readingView():`${yunCard()}<div class="two-columns">${elementsCard(r)}<section class="card"><h2>月令格局候选 · ${esc(r.structure.name)}</h2><p>${esc(r.structure.reason)}</p><p class="fine">${r.structure.note}</p></section></div>`}<section class="card"><div class="section-title"><h2>${f?'岁运与原局关系':'原局干支关系'}</h2><button class="text-button" data-tab="rules">配置显示 ›</button></div>${relationsHTML([...(f?.relations||r.relations),...r.wholePillars])}<p class="fine">这里只识别组合，不自动推断合化成局或事件吉凶。</p></section>${fortuneRulesView()}${notesCard()}`;}
function baziChart(f){const r=state.result;if(state.baziMode==='reading')return `<section class="card chart-card">${summary()}<div class="reading-pillar-strip">${r.pillars.map(p=>`<div><small>${p.label} · ${p.god}</small><b>${char(p.gan,p.elements[0])}${char(p.zhi,p.elements[1])}</b></div>`).join('')}</div></section>`;return `<section class="card chart-card">${summary()}${pillarTable(r,f?.pillars||[])}<div class="aux-strip">${Object.entries(r.auxiliary).map(([k,v])=>`<span>${k} <b>${esc(v)}</b></span>`).join('')}<span>${+state.current.sect===1?'23点':'零点'}换日</span></div>${r.minutePillar?`<div class="minute-strip"><span class="tag">第五柱</span><b>${r.minutePillar.value}</b><span>${r.minutePillar.god} · ${r.minutePillar.range}</span><button class="text-button" data-action="minute-detail">算法依据 ›</button></div>`:''}<div class="chart-foot">人元司令 <b>${r.commander.stem}</b> · 入${r.commander.term}后 ${r.commander.elapsed.toFixed(2)} 日 <button class="text-button" data-action="commander-detail">分日表 ›</button><br>${r.previousTerm.name} ${r.previousTerm.date}　→　${r.nextTerm.name} ${r.nextTerm.date}（UTC+8）</div></section>`;}
let readingCache=null;
function getReading(){const key=JSON.stringify([state.current,state.flowDate,state.flowTime]);if(readingCache?.key!==key)readingCache={key,value:analyzeBazi(state.result,{date:state.flowDate,time:state.flowTime,flow:getFlow()})};return readingCache.value;}
function evidenceHTML(items){return `<details class="reading-evidence"><summary>查看判断依据</summary><ul>${items.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`;}
function readingView(){const r=getReading(),s=r.strength,p=r.preferences,t=r.timing;return `<section class="card reading-intro"><div class="section-title"><h2>八字综合研习报告</h2><button class="secondary" data-action="export-reading">导出解读</button></div><p class="fine">${esc(r.scope)}</p><p class="fine">${esc(r.identity.ruleContext)}</p><div class="reading-synthesis">${r.summary.map(x=>`<p>${esc(x)}</p>`).join('')}</div><div class="reading-overview"><div><small>日主 / 月令</small><b>${r.identity.day}${r.identity.element} / ${s.season.month}月</b><span>${s.season.label} · ${r.identity.element}${s.season.state}</span></div><div><small>扶抑复核</small><b>${s.status==='strong'?'偏旺候选':s.status==='weak'?'偏弱候选':'强弱待辨'}</b><span>${s.roots.length}处同类藏根 · ${s.supports.length}位透干印比</span></div><div><small>月令格局</small><b>${esc(r.structure.name)}</b><span>${esc(r.structure.method)}取格</span></div><div><small>季节调候</small><b>${esc(r.climate.summary)}</b><span>与扶抑分别判断</span></div></div><p class="fine">藏根处数和透干位数是可核对的盘面记录，不是旺衰得分。</p></section>
 <div class="reading-grid">${s.methods.map(m=>`<article class="card"><h3>${esc(m.name)} · ${esc(m.conclusion)}</h3>${evidenceHTML(m.evidence)}</article>`).join('')}</div>
 <section class="card"><h2>规则与分歧</h2><p>${esc(s.rule)}</p>${s.disagreements.map(x=>`<p class="reading-conflict">${esc(x)}</p>`).join('')}<p class="fine">${esc(s.season.note)} ${esc(s.limits)}</p></section>
 <section class="card"><h2>格局条件 · ${esc(r.structure.name)}</h2><p>${esc(r.structure.conclusion)}</p>${evidenceHTML(r.structure.establishment)}<div class="report-combinations">${r.structure.combinations.map(x=>`<article><h3><span class="tag">${esc(x.kind)}</span> ${esc(x.name)}</h3><p>${esc(x.body)}</p>${evidenceHTML(x.evidence)}</article>`).join('')||'<p class="fine">未命中当前透干组合，不等于没有可用的格局路线。</p>'}</div></section>
 <div class="reading-grid"><section class="card"><h2>喜忌候选</h2><p>${esc(p.conclusion)}</p><div class="preference-pairs"><span>候选 <b>${p.assist.join('、')||'待辨'}</b></span><span>慎增 <b>${p.restrain.join('、')||'待辨'}</b></span></div><p class="fine">${esc(p.note)}</p></section><section class="card"><h2>季节调候</h2>${r.climate.items.map(x=>`<p><b>${x.element}</b> · ${esc(x.reason)}</p>`).join('')||`<p>${r.climate.summary}</p>`}${evidenceHTML([r.climate.evidence,r.climate.note])}</section></div>
 ${p.conflicts.length?`<section class="card"><h2>扶抑与调候冲突</h2>${p.conflicts.map(x=>`<p class="reading-conflict">${esc(x)}</p>`).join('')}</section>`:''}
 <section class="card"><h2>特殊格筛查</h2><div class="report-combinations">${r.specials.map(x=>`<article><h3>${esc(x.name)} · ${esc(x.status)}</h3><p>${esc(x.body)}</p>${evidenceHTML(x.evidence)}</article>`).join('')}</div></section>
 <section class="card"><h2>岁运同参 · ${esc(t.date)} ${esc(t.time)}</h2><p><b>大运 ${esc(t.decade?.label||'未配')}</b> ${t.decade?.from?` · ${t.decade.from} 至 ${t.decade.to}（UTC+8，右界不含）`:''}</p><p class="fine">${esc(t.decade?.note||'')}</p><div class="table-scroll"><table class="data-table report-flow"><thead><tr><th>层级</th>${t.items.map(x=>`<th>${esc(x.label)}</th>`).join('')}</tr></thead><tbody><tr><th>干支</th>${t.items.map(x=>`<td><b>${x.value}</b></td>`).join('')}</tr><tr><th>天干十神</th>${t.items.map(x=>`<td>${x.god}</td>`).join('')}</tr><tr><th>作用方向</th>${t.items.map(x=>`<td>${esc(x.body)}</td>`).join('')}</tr></tbody></table></div>${evidenceHTML(t.items.flatMap(x=>x.evidence))}<details class="reading-evidence"><summary>岁运与原局的合冲 / 同柱 · ${t.relations.length}项</summary>${relationsHTML(t.relations)}</details><p class="fine">${esc(t.note)}</p></section>
 <section class="card"><h2>分主题解读</h2><div class="report-combinations">${r.themes.map(x=>`<article><h3>${esc(x.name)}</h3><p>${esc(x.body)}</p>${evidenceHTML(x.evidence)}</article>`).join('')}</div></section>
 <details class="card reading-methods"><summary>计算依据与报告版本 · ${r.version}</summary>${r.sources.map(x=>`<p class="fine">${esc(x)}</p>`).join('')}</details>`;}
function notesCard(){return `<section class="card notes-card"><div class="section-title"><h2>案例笔记</h2><small>三栏独立保存 · 无需登录</small></div><label>标签<input id="record-tags" value="${esc(state.recordTags)}" maxlength="150" placeholder="例如：研习、复盘"></label><div class="note-grid"><label>研习笔记<textarea id="chart-note" maxlength="50000" rows="5" placeholder="记录判断依据与待验证事项">${esc(state.note)}</textarea></label><label>命主反馈<textarea id="feedback-note" maxlength="50000" rows="5" placeholder="记录实际经历与后续反馈">${esc(state.feedback)}</textarea></label><label>师傅点评<textarea id="commentary-note" maxlength="50000" rows="5" placeholder="记录批注、复盘与修正">${esc(state.commentary)}</textarea></label></div><div class="notes-footer"><span>编辑后请存入档案</span><button class="primary" data-action="save">保存本页记录</button></div></section>`;}

let ziweiCache=null;
function getZiwei(){const key=JSON.stringify([state.current,state.flowDate,state.flowTime]);if(ziweiCache?.key!==key)ziweiCache={key,value:ziwei(state.current,state.flowDate,state.flowTime)};return ziweiCache.value;}
function ziweiView(){const z=getZiwei(),scope=state.ziweiScope,flow=z.flow?.[scope];const positions={巳:[1,1],午:[1,2],未:[1,3],申:[1,4],辰:[2,1],酉:[2,4],卯:[3,1],戌:[3,4],寅:[4,1],丑:[4,2],子:[4,3],亥:[4,4]},p=z.palaces[state.palace]||z.palaces[0],selected=p.index,related=[selected,(selected+4)%12,(selected+6)%12,(selected+8)%12];return heading('','紫微斗数','本命 / 大限 / 小限 / 流年 / 流月 / 流日 / 流时 · 宫干飞化',saveActions())+flowControls()+`<div class="subnav">${[['origin','本命'],['decadal','大限'],['age','小限'],['yearly','流年'],['monthly','流月'],['daily','流日'],['hourly','流时']].map(([id,t])=>`<button data-scope="${id}" class="${scope===id?'selected':''}">${t}</button>`).join('')}</div><section class="card ziwei-card">${summary()}<div class="ziwei-grid"><div class="ziwei-center"><h2>${esc(z.fiveElementsClass)}</h2><b>命主 ${esc(z.soul)}　身主 ${esc(z.body)}</b><p>命宫 ${esc(z.earthlyBranchOfSoulPalace)} · 身宫 ${esc(z.earthlyBranchOfBodyPalace)}</p><p>${esc(z.lunarDate)}<br>${esc(z.time)} · ${esc(z.timeRange)}</p><hr><b>${scope==='origin'?'本命盘':`${flow?.name||''} ${flow?.heavenlyStem||''}${flow?.earthlyBranch||''}`}</b>${flow?`<p class="mutagen-line">${flow.mutagen.map((n,i)=>`${n}化${['禄','权','科','忌'][i]}`).join('　')}</p>`:''}<p>选中 ${esc(p.name)}<br>高亮：本宫、对宫、三合宫</p><small>${state.current.ziweiAlgorithm==='zhongzhou'?'中州安星':'通行安星'} / ${state.current.ziweiType==='earth'?'地盘':state.current.ziweiType==='human'?'人盘':'天盘'}<br>年界：${state.current.ziweiYearDivide==='exact'?'立春':'正月初一'}</small></div>${z.palaces.map((p,index)=>{const pos=positions[p.earthlyBranch],all=[...p.majorStars,...p.minorStars],flowStars=flow?.stars?.[index]||[];return `<button class="palace ${index===selected?'palace-selected':related.includes(index)?'palace-related':''}" data-palace="${index}" style="grid-row:${pos[0]};grid-column:${pos[1]}"><div class="palace-top"><b>${esc(p.name)}${p.isBodyPalace?'·身':''}</b><small>${esc(p.heavenlyStem+p.earthlyBranch)}</small></div><div class="star-columns">${all.map(s=>`<span class="${s.type==='major'?'major-star':''}"><b>${esc(s.name)}</b><small>${esc(s.brightness||'')}</small>${s.mutagen?`<i class="mutagen">${esc(s.mutagen)}</i>`:''}${flow?.mutagen?.includes(s.name)?`<i class="flow-mutagen">${['禄','权','科','忌'][flow.mutagen.indexOf(s.name)]}</i>`:''}</span>`).join('')||'<span class="muted">空宫</span>'}</div><p class="minor-stars">${p.adjectiveStars.map(s=>esc(s.name)).join(' ')}</p>${flow?`<div class="flow-palace"><b>${esc(flow.palaceNames[index])}</b> ${flowStars.map(s=>esc(s.name)).join(' ')}</div>`:''}<div class="palace-bottom"><small>${p.decadal.range.join('—')}岁 · ${esc(p.changsheng12)}</small><small>${esc(p.boshi12)}</small></div></button>`;}).join('')}</div></section><section class="card"><div class="section-title"><h2>${esc(p.name)} · 宫干${esc(p.heavenlyStem)}飞化</h2><button class="secondary" data-palace-detail="${selected}">星曜详解</button></div><div class="flight-grid">${z.flights[selected].map(f=>`<button data-palace="${f.target}"><b>化${f.mutagen}</b><span>${f.self?'自化':`→ ${esc(f.name)}`}</span></button>`).join('')}</div><p>三方四正：${related.map(i=>esc(z.palaces[i].name)).join(' / ')}　小限虚岁：${p.ages.join('、')}</p><p class="fine">飞化与运限采用 iztro 所选规则；尚未与原版服务器逐盘校验。</p></section><section class="card"><h2>大限选择</h2><div class="decades">${z.decadals.map(d=>`<button data-ziwei-year="${d.yearRange[0]}"><small>${d.yearRange.join('—')}</small><b>${esc(d.palaceName)}</b><span>${d.ageRange.join('—')}岁</span></button>`).join('')}</div></section>${notesCard()}`;}
function qimenView(){const q=qimen(state.current),{chart:c,patterns}=q;return heading('','奇门遁甲','时家转盘 · 拆补 / 置闰 / 手动定局',saveActions())+`<div class="subnav">${[['拆補','拆补'],['置闰','置闰（符头法）'],['手动','手动定局']].map(([v,n])=>`<button data-qimen-method="${v}" class="${v===(['符頭','符头'].includes(state.current.qimenMethod)?'置闰':state.current.qimenMethod)?'selected':''}">${n}</button>`).join('')}</div><div class="toolbar"><button class="secondary" data-shift="-120">← 前一时辰</button><button class="secondary" data-action="now">此刻起盘</button><button class="secondary" data-shift="120">后一时辰 →</button></div><section class="card qimen-card">${summary()}<div class="qimen-banner"><div><b>${esc(c.陰陽)}遁 ${c.局數} 局</b><span>${esc(c.節氣)} · ${esc(c.三元)} · ${esc(c.定局法)}</span></div><p>旬首 ${esc(c.旬首)} · 符首 ${esc(c.符首)}<br>值符 ${esc(c.值符)} · 值使 ${esc(c.值使)}</p><small>上南下北</small></div><div class="qimen-grid">${c.方位.map((name,i)=>`<button class="qimen-palace ${i===4?'qimen-center':''}" data-qimen="${i}"><div class="palace-top"><b>${esc(name)}宫</b><span>${esc(c.八神[i])}</span></div><div class="qimen-core"><strong>${esc(c.天盤[i])}</strong><div><b>${esc(c.天門[i]||'中宫')}</b><span>${esc(c.九星[i])}</span></div></div><div class="palace-bottom"><small>地盘 ${esc(c.地盤[i])}</small><small>${esc(c.九宮[i])}</small></div><div class="qimen-hits">${patterns.filter(p=>p.宮===name).map(p=>esc(p.格)).slice(0,4).join(' · ')}</div></button>`).join('')}</div></section>${qimenTimingView(q)}<section class="card"><h2>格局详解 · ${patterns.length} 项</h2><div class="pattern-list">${patterns.map(p=>`<details><summary><b>${esc(p.格)}</b><small>${esc(p.宮||'全盘')} · ${esc(p.吉凶||p.類||'')}</small></summary><p>${esc(p.細節)}</p>${(p.出處||[]).map(s=>`<p class="fine">${esc(typeof s==='string'?s:Object.values(s).join(' · '))}</p>`).join('')}</details>`).join('')||'<p>未命中当前格局规则。</p>'}</div><p class="fine">手动局数在左侧排盘设置中指定。阴盘和命理奇门尚未实现；置闰采用日粒度规则，详见上方定局依据。</p></section>${notesCard()}`;}
function qimenTimingView({timing:t,comparison}){return `<section class="card qimen-trace"><div class="section-title"><h2>定局依据 · ${esc(t.method)}</h2><small>基准 ${esc(t.basis)}</small></div><div class="qimen-trace-head"><span>实际节气 <b>${esc(t.actualTerm)}</b></span><span>用局节气 <b>${esc(t.usedTerm||'手动指定')}</b></span>${t.state?`<span>超接 <b>${esc(t.state)} ${t.gap}日</b></span><span>闰局 <b>${t.isLeap?'是 · 重用本气三元':'否'}</b></span>`:''}</div>${t.upperHead?`<div class="aux-strip"><span>上元符头 <b>${t.upperHead} · ${t.cycleStart}</b></span><span>本元符头 <b>${t.head} · ${t.yuanStart}</b></span><span>本循环至 <b>${t.cycleEnd} 零点</b></span></div>`:''}<p>${esc(t.rule)}</p>${t.leapTrigger?`<p class="reading-conflict">本次置闰触发：${esc(t.leapTrigger.term)}在${t.leapTrigger.date}（UTC+8），距本次上元符头${t.leapTrigger.gap}个历日，达到8日门槛。上方接气天数描述的是所重用本气与符头的距离，二者不同。</p>`:''}<p class="fine">${esc(t.limitation)}${t.state?' 超接日数为历日差，不是含头计数。':''}</p><div class="qimen-method-compare">${comparison.map(x=>`<div><small>${esc(x.method)}</small><b>${esc(x.yinYang)}遁${x.ju}局</b><span>${esc(x.term)} ${esc(x.yuan)}${x.state?' · '+esc(x.state):''}${x.isLeap?' · 闰局':''}</span></div>`).join('')}</div><p class="fine">${esc(t.source)}</p></section>`;}
function compareView(){const r=state.compare;return heading('','双人合盘','双盘并排 · 跨盘关系 · 五行对照',saveActions())+`<div class="compare-layout"><section class="card partner-card"><h2>乙方资料</h2><form id="partner-form">${formFields(state.partner,true)}<button class="primary full" type="submit">对照排盘</button></form><p class="fine">乙方沿用甲方时区、经度、换日与流派设置。</p></section><section class="card"><h2>${esc(state.current.name)} × ${esc(state.partner.name)}</h2>${r?`<h3>甲方</h3>${pillarTable(r.left)}<h3>乙方</h3>${pillarTable(r.right)}<div class="compare-elements">${ELEMENTS.map(e=>`<span class="${colors[e]}">${e}：${r.left.counts[e]} / ${r.right.counts[e]}</span>`).join('')}</div><h3>跨盘关系</h3>${relationsHTML(r.relations)}`:'<div class="empty-state"><h3>填写乙方资料后开始对照</h3><p>按明确规则列出关系，不生成婚配评分。</p></div>'}</section></div>${notesCard()}`;}
function calendarView(){const c=calendarMonth(state.calendarDate),a=almanac(state.calendarDate);return heading('','万年历',`${c.year} 年 ${c.month} 月 · 传统历法资料`, `<button class="secondary" data-cal-month="-1">上月</button><button class="secondary" data-action="calendar-today">今天</button><button class="secondary" data-cal-month="1">下月</button>`)+`<div class="calendar-layout"><section class="card calendar-card"><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<span class="weekday">${x}</span>`).join('')}${Array(c.offset).fill('<div></div>').join('')}${c.days.map(d=>`<button class="calendar-day ${d.date===state.calendarDate?'selected':''}" data-cal-date="${d.date}"><strong>${d.day}</strong><span>${esc(d.lunar)}</span><small>${esc(d.term||d.festivals[0]||'')}</small></button>`).join('')}</div></section><section class="card almanac"><h2>${a.date}</h2><p>${esc(a.lunar)}　${a.gz.join('　')}</p><div class="yi-ji"><b>宜</b><p>${a.yi.join(' · ')}</p></div><div class="yi-ji ji"><b>忌</b><p>${a.ji.join(' · ')}</p></div><dl class="data-list"><dt>冲煞</dt><dd>冲${a.chong} 煞${a.sha}</dd><dt>值神 / 建除</dt><dd>${a.spirit}（${a.spiritLuck}） / ${a.officer}日</dd><dt>九星 / 物候</dt><dd>${a.nineStar} / ${a.wuHou}</dd><dt>方位</dt><dd>${Object.entries(a.positions).map(([k,v])=>k+v).join(' · ')}</dd><dt>胎神</dt><dd>${a.fetal}</dd><dt>吉神</dt><dd>${a.good.join('、')}</dd><dt>凶煞</dt><dd>${a.bad.join('、')}</dd><dt>彭祖百忌</dt><dd>${a.pengzu.join('；')}</dd></dl><button class="primary" data-use-date="${a.date}">此日排盘</button></section></div><section class="card"><h2>十二时辰（早子、晚子分列）</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>干支 / 时间</th><th>值神</th><th>宜</th><th>忌</th><th>冲煞</th></tr></thead><tbody>${a.times.map(t=>`<tr><td><b>${t.value}</b><small>${t.range}</small></td><td>${t.god} ${t.luck}</td><td>${t.yi.join('、')}</td><td>${t.ji.join('、')}</td><td>冲${t.chong} 煞${t.sha}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>${c.year} 年二十四节气 · UTC+8</h2><div class="term-grid">${solarTerms(c.year).map(t=>`<button data-cal-date="${t.date.slice(0,10)}"><b>${t.name}</b><span>${t.date.slice(5)}</span></button>`).join('')}</div></section>`;}
function wuyunView(){const w=wuYunLiuQi(state.wuyunYear);return heading('','五运六气','岁运、司天、在泉与六步主客气（节气时刻按 UTC+8）',`<button class="secondary" data-wuyun-step="-1">上一年</button><input id="wuyun-year" type="number" min="1901" max="2099" value="${w.year}" aria-label="运气年份"><button class="secondary" data-wuyun-step="1">下一年</button>`)+`<section class="card"><div class="wuyun-summary"><div><small>${w.year} · ${w.value}年</small><h2>${w.movement}运${w.state}</h2></div><div><small>司天</small><b>${w.sitian}</b></div><div><small>在泉</small><b>${w.zaiquan}</b></div></div><div class="table-scroll"><table class="data-table qi-table"><thead><tr><th>六步</th><th>初之气</th><th>二之气</th><th>三之气</th><th>四之气</th><th>五之气</th><th>终之气</th></tr></thead><tbody><tr><th>主气</th>${w.steps.map(s=>`<td>${s.host}</td>`).join('')}</tr><tr><th>客气</th>${w.steps.map(s=>`<td><b>${s.guest}</b></td>`).join('')}</tr><tr><th>交接节气</th>${w.steps.map(s=>`<td>${s.start?.slice(5,16)}<small>至 ${s.end?.slice(5,16)}</small></td>`).join('')}</tr></tbody></table></div></section><section class="card"><h2>排布依据</h2><p>${w.formula}</p><p>主气按厥阴风木、少阴君火、少阳相火、太阴湿土、阳明燥金、太阳寒水固定顺序排布。六步分别以大寒、春分、小满、大暑、秋分、小雪分段，时刻由本地节气引擎计算。</p><p class="fine">本页重建传统运气历法的基础结构，未实现原版全年运气叙述与五步主客运算法。</p></section>`;}
function reverseView(){const values=state.reverseValues||state.result.pillars.map(p=>p.value);return heading('','四柱反查','按四柱查找公历代表时刻 · 1901—2099 · UTC+8')+`<section class="card"><form id="reverse-form"><div class="reverse-fields">${values.map((v,i)=>`<label>${['年柱','月柱','日柱','时柱'][i]}<input name="p${i}" value="${v}" maxlength="2" required></label>`).join('')}<label>起始年<input name="start" type="number" min="1901" max="2099" value="1901" required></label><label>结束年<input name="end" type="number" min="1901" max="2099" value="${+today.date.slice(0,4)}" required></label></div><button class="primary" type="submit">反查公历</button><p class="fine">采用当前子时换日规则及精确立春年界。选取结果时同步设为精确立春、UTC+8。列出匹配时辰内的代表时刻；不展开时辰内全部分钟，不用于真太阳时或历史时区反解。</p></form><div id="reverse-results">${reverseResults()}</div></section>`;}
function reverseResults(){return state.reverse.length?`<h3>${state.reverse.length} 个匹配代表时刻</h3><div class="result-grid">${state.reverse.map(r=>`<button class="secondary" data-reverse-date="${r.date}" data-reverse-time="${r.time}">${r.date} ${r.time} → 排盘</button>`).join('')}</div>`:'<p class="muted">查询结果将显示在这里。</p>';}
function knowledgeResults(){const q=state.query.trim().toLowerCase(),items=[...(state.knowledgeType==='stars'?[]:glossary.map(x=>({name:x.term,type:'术语',text:x.text}))),...(state.knowledgeType==='terms'?[]:stars.map(x=>({name:x.name,type:'星曜',text:Object.entries(x.basics||{}).map(([k,v])=>`${k}：${v}`).join('\n')})))].filter(x=>(x.name+' '+x.text).toLowerCase().includes(q));return `<p class="result-count">${items.length} 条匹配 · 八字术语 168 / 紫微星曜 83</p><div class="knowledge-list">${items.slice(0,100).map(x=>`<button data-knowledge="${esc(x.name)}" data-kind="${x.type}"><span class="tag">${x.type}</span><h3>${esc(x.name)}</h3><p>${esc(x.text.slice(0,100))}…</p></button>`).join('')}</div>${items.length>100?'<p class="fine">先显示前 100 条，请搜索缩小范围。</p>':''}`;}
function knowledgeView(){return heading('','知识库','安装包本地术语与星曜资料 · 可全文搜索')+`<section class="card"><div class="search-controls"><input id="knowledge-query" type="search" value="${esc(state.query)}" placeholder="搜索术语、星曜或释义" aria-label="搜索知识库"><select id="knowledge-type" aria-label="资料类型">${selectOptions([['all','全部'],['terms','八字术语'],['stars','紫微星曜']],state.knowledgeType)}</select></div><div id="knowledge-results">${knowledgeResults()}</div></section>`;}
function recordsView(){return heading('','命盘档案',`${records.length} 份本地记录 · 分类管理与案例复盘`, `<button class="secondary" data-action="import">导入备份</button><button class="primary" data-action="export">导出全部</button>`)+`<section class="card"><div class="search-controls"><input id="archive-query" type="search" value="${esc(state.archiveQuery)}" placeholder="搜索姓名、标签、日期、笔记" aria-label="搜索档案"><button class="secondary ${state.onlyStar?'selected':''}" data-action="only-star">${state.onlyStar?'★ 仅星标':'☆ 星标筛选'}</button></div><div class="category-tabs">${[['all','全部'],...Object.entries(CATEGORIES)].map(([id,n])=>`<button data-category="${id}" class="${state.archiveCategory===id?'selected':''}">${n} <small>${id==='all'?records.length:records.filter(r=>(r.category||'bazi')===id).length}</small></button>`).join('')}</div><div id="archive-results">${archiveResults()}</div></section>`;}
function archiveResults(){const q=state.archiveQuery.toLowerCase(),list=records.filter(r=>(!state.onlyStar||r.starred)&&(state.archiveCategory==='all'||(r.category||'bazi')===state.archiveCategory)&&JSON.stringify([r.input.name,r.input.date,r.note,r.feedback,r.commentary,r.tags]).toLowerCase().includes(q));return `<div class="archive-grid">${list.map(r=>`<article class="archive-card"><div class="section-title"><div><span class="tag">${CATEGORIES[r.category]||CATEGORIES.bazi}</span><h3>${esc(r.input.name)}</h3></div><button class="text-button" data-star="${esc(r.id)}" aria-label="星标 ${esc(r.input.name)}">${r.starred?'★':'☆'}</button></div><p>${esc(r.input.date)} ${esc(r.input.time)} · ${+r.input.gender===1?'男':'女'}</p><b>${esc(r.pillars?.join('　'))}</b><p class="fine">${esc(r.tags||'')}</p><p class="archive-note">${esc((r.note||'暂无笔记').slice(0,100))}</p><div class="archive-footer"><button class="text-button danger" data-delete="${esc(r.id)}">删除</button><button class="secondary" data-multi-add="${esc(r.id)}">加入多盘</button><button class="secondary" data-record-compare="${esc(r.id)}">设为乙方</button><button class="primary" data-open="${esc(r.id)}">打开</button></div></article>`).join('')||'<div class="empty-state"><h3>没有匹配档案</h3><p>排盘后点击“存入档案”，可保存命盘与笔记。</p></div>'}</div>`;}
function bookPages(book){return book.text.match(/[\s\S]{1,2400}/g)||[''];}
function readerView(){const b=books.find(b=>b.id===state.readerId);if(!b)return heading('','本地书房','导入自己的 TXT / Markdown 文本，离线阅读、书签与系统朗读',`<button class="primary" data-action="import-book">导入文本</button>`)+`<div class="archive-grid">${books.map(b=>`<article class="card"><h3>${esc(b.title)}</h3><p>${b.text.length.toLocaleString()} 字 · 上次读至第 ${(b.page||0)+1} 页</p><button class="primary" data-book="${esc(b.id)}">继续阅读</button></article>`).join('')||'<section class="card empty-state"><h2>把研习资料带到本机</h2><p>支持 UTF-8 文本；每本最多 2 MB。书页、阅读位置和书签保存在本机，可随全部备份导出。</p><p class="fine">原应用只有远程目录的古籍未作为完整正文收入。</p></section>'}</div>`;const pages=bookPages(b),page=Math.min(state.readerPage,pages.length-1);state.readerPage=page;return heading('',b.title,`${page+1} / ${pages.length} 页 · ${(b.bookmarks||[]).length} 个书签`, `<button class="secondary" data-action="reader-back">返回书架</button><button class="secondary" data-action="bookmark">${(b.bookmarks||[]).includes(page)?'★ 移除书签':'☆ 添加书签'}</button>`)+`<section class="card reader-card"><div class="reader-toolbar"><button class="secondary" data-reader-step="-1">上一页</button><label>跳页<input id="reader-page" type="number" min="1" max="${pages.length}" value="${page+1}"></label><button class="secondary" data-reader-step="1">下一页</button><button class="secondary" data-action="read-aloud">朗读本页</button><button class="secondary" data-action="stop-reading">停止</button></div><div class="search-controls"><input id="reader-query" type="search" value="${esc(state.readerQuery)}" placeholder="搜索本书文字" aria-label="搜索本书"><button class="secondary" data-action="reader-search">查找</button></div><div class="bookmarks">${(b.bookmarks||[]).map(p=>`<button class="rule-chip" data-reader-page="${p}">第${p+1}页</button>`).join('')}</div><div class="reader-prose">${esc(pages[page])}</div></section>`;}
function homeView(){const now=nowInput(state.current),r=calculate(now);const tools=[['case','案例解析','从综合解读开始，记录反馈与复盘','bazi'],['compare','双人合盘','并排核对十神与跨盘干支关系','compare'],['multi','多盘对比','最多四份命盘，逐项比较差异','multi'],['wealth','财星研习','正偏财定位、食伤与比劫对照','wealth'],['calendar','万年历','农历、时辰、黄历与节气','calendar'],['wuyun','五运六气','岁运、司天、在泉与六步主客气','wuyun'],['qimen','奇门遁甲','拆补、置闰与手动定局','qimen'],['ziwei','紫微斗数','三方四正、四化与运限切换','ziwei']];return heading('WORKSPACE / 本机研习','研习工作台','从一张命盘开始，将计算、解读和案例放在一起。',`<button class="primary" data-action="edit-input">＋ 新建排盘</button>`)+`<section class="workspace-hero"><div><span class="eyebrow">此刻四柱 · ${utcLabel(state.current)}</span><div class="clock-pillars">${r.pillars.map(p=>`<div><small>${p.label}</small><b>${p.value}</b></div>`).join('')}</div><p>${now.date} ${now.time} · ${esc(r.lunar)}<button class="text-button" data-tab="home">刷新</button></p></div><div class="hero-stat"><b>${records.length.toString().padStart(2,'0')}</b><span>本机研习记录</span><button data-tab="records">打开档案 →</button></div></section><div class="section-title"><h2>常用工具</h2><small>所有计算与记录均可离线使用</small></div><div class="tool-grid">${tools.map(([id,name,text,ico])=>`<button class="tool-card" ${id==='case'?'data-action="case"':`data-tab="${id}"`}><span class="tool-icon">${icon(ico)}</span><span><b>${name}</b><small>${text}</small></span><i>↗</i></button>`).join('')}</div><section class="card recent-records"><div class="section-title"><h2>最近研习</h2><button class="text-button" data-tab="records">全部记录 →</button></div>${records.slice(0,4).map(r=>`<button data-open="${esc(r.id)}"><span class="avatar">${esc(r.input.name.slice(0,1))}</span><b>${esc(r.input.name)}</b><small>${CATEGORIES[r.category]||CATEGORIES.bazi}</small><span>${esc(r.pillars?.join('　')||'')}</span><small>打开 ›</small></button>`).join('')||'<p class="fine">尚无档案。计算命盘后，可将笔记、反馈和点评一起保存。</p>'}</section>`;}
const shenshaVisible=h=>!prefs.hiddenShensha.includes(h.name);
function fortuneRulesView(){if(!prefs.showShensha)return '';const r=state.result,{targets,hits}=fortuneShensha(r,state.decade,shensha);return `<section class="card fortune-rules"><div class="section-title"><h2>神煞细览</h2><small>原局 / 所选大运 / 十个流年</small></div><p class="fine">以原局年干、日干、年支、日支或月令为依据查目标柱；不是用流年替换出生资料。点击名称查看命中条件。</p><div class="two-columns"><details open><summary>原局神煞</summary><div class="rule-rows">${r.pillars.map(p=>`<div><b>${p.label} ${p.value}</b><span>${ruleChips(r.shensha.filter(h=>h.target===p.label))}</span></div>`).join('')}</div></details><details open><summary>大运 / 流年神煞</summary><div class="rule-rows">${targets.map(p=>`<div class="${p.label==='大运'?'decade-rule':''}"><b>${p.label} ${p.value}</b><span>${ruleChips(hits.filter(h=>h.target===p.label))}</span></div>`).join('')||'<p class="fine">童限无独立大运柱。</p>'}</div></details></div></section>`;}
function ruleChips(hits){return [...new Set(hits.filter(shenshaVisible).map(h=>h.name))].map(n=>`<button class="rule-chip" data-shensha="${n}">${n}</button>`).join('')||'<small>—</small>';}
function wealthView(){const r=wealthStudy(state.result),rows=(list)=>list.length?list.map(h=>`<tr><td>${h.position}</td><td><b>${h.stem}</b></td><td>${h.god}</td><td>${h.layer}</td></tr>`).join(''):'<tr><td colspan="4">当前原局未见</td></tr>';return heading('STUDY / 财星','八字财星研习','定位符号、核对结构、结合实际案例复盘',saveActions())+summary()+`<section class="card wealth-intro"><div class="section-title"><h2>${r.day}日主 · 财星属${r.element}</h2><span class="tag">我克者为财</span></div><p>${esc(r.summary)}</p><p class="fine">本页分析传统十神结构，不生成资产估值、投资建议或财富等级。</p></section><div class="reading-grid">${[['原局正财 / 偏财',r.wealth,'财星位置'],['食神 / 伤官',r.output,'食伤生财的结构条件'],['比肩 / 劫财',r.peers,'同类分担与竞争的结构条件']].map(([n,items,sub])=>`<section class="card"><h2>${n}</h2><p class="fine">${sub}</p><div class="table-scroll"><table class="data-table wealth-table"><thead><tr><th>位置</th><th>天干</th><th>十神</th><th>层次</th></tr></thead><tbody>${rows(items)}</tbody></table></div></section>`).join('')}<section class="card"><h2>如何结合综合解读</h2><p>财星出现只说明关系存在，还需核对月令、通根、透干与日主承受条件。食伤、比劫分别列示，不把数量直接判作财运吉凶。</p><button class="secondary" data-action="case">打开综合解读与案例笔记 →</button></section></div>${notesCard()}`;}
function multiView(){const inputs=[state.current,...state.multiInputs],r=inputs.length>1?multiStudy(inputs):null;return heading('STUDY / COMPARE','多盘对比','当前盘＋最多三份档案 · 每份沿用自己的排盘规则',saveActions())+`<section class="card"><div class="section-title"><h2>对比命盘 <small>${inputs.length} / 4</small></h2><button class="secondary" data-tab="records">从档案加入命盘</button></div><div class="selected-charts">${inputs.map((i,n)=>`<span><b>${esc(i.name)}</b><small>${esc(i.date)} ${esc(i.time)}</small>${n?`<button data-multi-remove="${n-1}" aria-label="移除 ${esc(i.name)}">×</button>`:'<small>当前盘</small>'}</span>`).join('')}</div></section>${r?`<section class="card"><div class="table-scroll"><table class="data-table multi-table"><thead><tr><th>对照项</th>${inputs.map(i=>`<th>${esc(i.name)}</th>`).join('')}</tr></thead><tbody>${[...['年柱','月柱','日柱','时柱'].map((n,k)=>[n,c=>`<b class="multi-pillar">${char(c.pillars[k].gan,c.pillars[k].elements[0])}${char(c.pillars[k].zhi,c.pillars[k].elements[1])}</b><small>${c.pillars[k].god}</small>`]),['日主',c=>c.pillars[2].gan+c.pillars[2].elements[0]],['月令格局',c=>esc(c.structure.name)],['五行表层计数',c=>ELEMENTS.map(e=>`${e} ${c.counts[e]}`).join(' / ')],['命宫 / 身宫',c=>c.auxiliary.命宫+' / '+c.auxiliary.身宫],['子时换日',c=>+c.input.sect===1?'23点':'零点'],['年柱交接',c=>yearBoundaryName(c.input.yearBoundary)]].map(([n,fn])=>`<tr><th>${n}</th>${r.charts.map(c=>`<td>${fn(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="card"><h2>两两跨盘关系</h2>${r.pairs.map(p=>`<details class="pair-detail"><summary>${esc(inputs[p.a].name)} × ${esc(inputs[p.b].name)} <small>${p.relations.length} 项规则命中</small></summary>${relationsHTML(p.relations)}</details>`).join('')}<p class="fine">命中数量仅用于浏览，不表示亲密度、适合度或吉凶评分。</p></section>${notesCard()}`:'<section class="card empty-state"><div class="empty-icon">'+icon('multi')+'</div><h2>让差异并排可见</h2><p>先保存需要比较的命盘，再在档案中点“加入多盘”。<br>支持比较不同命主，也可保存同一命主的不同时间或规则方案。</p><button class="primary" data-tab="records">选择档案 →</button></section>'}`;}
const yearBoundaryName=v=>v==='springFestival'?'正月初一':v==='lichunDay'?'立春日零点':'立春交节时刻';
const RELATION_TYPES=['天干五合','天干相冲','地支六合','地支六冲','地支六害','地支相破','子卯相刑','刑支相见','地支自刑','三合齐备','三会齐备','三刑齐备','地支暗合','盖头','截脚'];
function rulesView(){const i=state.current;return heading('PREFERENCES / 规则','规则与显示','每一项注明计算口径；保存后重新计算当前命盘。')+`<form id="rules-form"><div class="settings-grid"><section class="card"><div class="section-title"><h2>时间与历法</h2><span class="tag">参与计算</span></div>${choice('sect','早晚子时',[[2,'零点换日'],[1,'23点换日']],i.sect)}${choice('yearBoundary','年柱交接',[['exact','立春交节时刻（默认）'],['lichunDay','立春当日零点（UTC+8）'],['springFestival','农历正月初一（UTC+8）']],i.yearBoundary)}<div class="form-pair"><label>标准时区 UTC<input name="utcOffset" type="number" min="-12" max="14" step="0.25" value="${i.utcOffset??8}"></label><label>经度<input name="longitude" type="number" min="-180" max="180" step="0.0001" value="${i.longitude}"></label></div><label class="check"><input name="trueSolar" type="checkbox" ${i.trueSolar?'checked':''}>真太阳时（近似均时差）</label><label class="check"><input name="dst" type="checkbox" ${i.dst?'checked':''}>输入含夏令时，先减一小时</label><p class="fine">节气使用定气法；年界选项只改变年柱、生肖、命身宫年干与大运顺逆，月柱仍按实际交节。精确交节以同一物理时刻判断。</p></section><section class="card"><div class="section-title"><h2>四柱与辅助盘法</h2><span class="tag">参与计算</span></div>${choice('structureMethod','格局取法',[['透干','月令藏干透干优先'],['本气','月令本气']],i.structureMethod)}${choice('yunSect','起运换算',[[2,'按分钟换算'],[1,'按时辰换算']],i.yunSect)}${choice('decadeCount','大运范围',[[12,'120年'],[8,'80年']],i.decadeCount)}${choice('palaceMethod','命宫月序',[['jie','按节换月'],['qi','过中气按下月']],i.palaceMethod)}<label class="check"><input name="minutePillar" type="checkbox" ${i.minutePillar?'checked':''}>显示分柱 · 时上五鼠遁，10分钟一段</label><p class="fine">身宫使用按节月序。分柱独立列示，不加入四柱旺衰、格局或神煞分析。人元司令使用下方公开分日表。</p></section><section class="card"><h2>紫微与奇门</h2>${choice('ziweiAlgorithm','紫微安星',[['default','通行'],['zhongzhou','中州']],i.ziweiAlgorithm)}${choice('ziweiType','盘式',[['heaven','天盘'],['earth','地盘（中州）'],['human','人盘（中州）']],i.ziweiType)}${choice('ziweiYearDivide','紫微年界',[['normal','正月初一'],['exact','立春']],i.ziweiYearDivide)}<label class="check"><input name="fixLeap" type="checkbox" ${i.fixLeap?'checked':''}>闰月过半按下月</label>${choice('qimenMethod','奇门定局',[['拆補','拆补'],['置闰','置闰（符头）'],['手动','手动']],['符頭','符头'].includes(i.qimenMethod)?'置闰':i.qimenMethod)}<div class="form-pair">${choice('qimenYinYang','阴阳遁',[['陽','阳遁'],['陰','阴遁']],i.qimenYinYang)}${choice('qimenJu','手动局数',Array.from({length:9},(_,n)=>[n+1,n+1+'局']),i.qimenJu)}</div></section><section class="card"><div class="section-title"><h2>阅读与盘面</h2><span class="tag">仅影响显示</span></div>${choice('theme','配色',[['cinnabar','墨色 / 朱砂'],['ochre','墨色 / 古铜'],['jade','墨色 / 青玉']],prefs.theme)}${choice('font','字号',[[13,'紧凑 13'],[14,'标准 14'],[16,'放大 16'],[18,'大字 18']],prefs.font)}${choice('ageMode','虚实岁',[['virtual','虚岁（原引擎岁数）'],['full','周岁（按公历生日列范围）']],prefs.ageMode)}${choice('hiddenOrder','藏干排列',[['qi','本气、中气、余气顺序'],['library','引擎原始顺序']],prefs.hiddenOrder)}<label class="check"><input name="showShensha" type="checkbox" ${prefs.showShensha?'checked':''}>显示原局及行运神煞</label><p class="fine">藏干使用固定表；此处可调排列顺序。关系和神煞筛选只影响盘面，综合解读仍使用完整四柱与关系。</p></section></div><section class="card"><div class="section-title"><h2>神煞设置 <small>${SHENSHA_NAMES.length} 类</small></h2><div><button type="button" class="text-button" data-action="enable-shensha">全选</button><button type="button" class="text-button" data-action="disable-shensha">全不选</button></div></div><p class="fine">年 / 日干查支、年 / 日支查三合组、月令查表；孤辰寡宿、红鸾天喜、丧门吊客披麻以年支查。红艳采用甲午乙申表；天德合以天德所临干支的五合或六合取配。点击盘面标签查看命中证据。</p><div class="rule-checks">${SHENSHA_NAMES.map(n=>`<label class="check"><input type="checkbox" name="enabledShensha" value="${n}" ${prefs.hiddenShensha.includes(n)?'':'checked'}>${n}</label>`).join('')}</div></section><section class="card"><h2>干支关系显示</h2><div class="rule-checks">${RELATION_TYPES.map(n=>`<label class="check"><input type="checkbox" name="enabledRelation" value="${n}" ${prefs.hideRelations.includes(n)?'':'checked'}>${n}</label>`).join('')}</div></section><section class="card rule-sources"><h2>口径与公开依据</h2><details><summary>分柱 · 五鼠遁</summary><p>一个时辰120分钟分12段，从时辰起点起每10分钟换一支。以时干代日干按五鼠遁起分干。区间左闭右开；00点接续23点起的子时。</p><p class="fine">伍立群《分柱程式之我見》，《新玄機》176期，2012年2月。原文有算例：2011-09-12 13:03，癸未时，壬子分柱。</p><code>fengshui-magazine.com.hk/No.176-Feb12/A2.htm</code></details><details><summary>命宫 · 按节 / 过中气换月</summary><p>寅1至丑12，月支数＋时支数不足14，以14减；达到14，以26减。年干依五虎遁配宫干。过中气换月口径仅作用于命宫。</p><p class="fine">苏民峰《八字讲义·第四章 推命宫胎元法》；默认按节口径沿用 lunar-javascript。</p><code>masterso.com/classroom/classroom2_1_4.php</code></details><details><summary>人元司令 · 分日表</summary><p>寅戊7丙7甲16；卯甲10乙20；辰乙9癸3戊18；巳戊5庚9丙16；午丙10己9丁11；未丁9乙3己18；申戊10壬3庚17；酉庚10辛20；戌辛9丁3戊18；亥戊7甲5壬18；子壬10癸20；丑癸9辛3己18。</p><p>从实际入节时刻起计连续24小时为一日，满边界后切换；末段持续到下一节。资料存在异表，此版采用琴鹤堂所列版本。</p><code>sohu.com/a/680760234_100084723</code></details><details><summary>节气、神煞与尚未覆盖的变体</summary><p>节气使用 lunar-javascript 1.7.7 的定气历法，未加入历史平气历重建。神煞采用明示查表，不将标签推导为个人事件。德秀采用月组德秀两类俱见的候选；学堂词馆采用年柱纳音同气的真学堂 / 词馆；元辰勾绞按年干阴阳与性别；天罗地网采用年 / 日支互见简法，不追加纳音、性别限制。血刃查表变体本版未收入。</p><code>itmao.com/m/html/634.html</code><code>zh.wikisource.org/wiki/三命通會/卷三</code><p class="fine">部分表存在年干 / 日干取法差异，本版保留固定来源范围。年柱交接提供精确立春、立春日零点、正月初一三种可复核年界；尚未确认原版“年柱交换”的全部选项。</p></details></section><div class="rules-save"><span>当前：${esc(i.name)} · ${yearBoundaryName(i.yearBoundary)}</span><button class="primary" type="submit">保存规则并重新计算</button></div></form>`;}
function saveRules(e){e.preventDefault();try{const f=new FormData(e.target),next={...state.current};for(const k of ['sect','utcOffset','longitude','yunSect','decadeCount','qimenJu'])next[k]=Number(f.get(k));for(const k of ['yearBoundary','palaceMethod','structureMethod','ziweiAlgorithm','ziweiType','ziweiYearDivide','qimenMethod','qimenYinYang'])next[k]=f.get(k);for(const k of ['trueSolar','dst','minutePillar','fixLeap'])next[k]=f.has(k);const result=calculate(next),nextPrefs={...prefs,theme:f.get('theme'),font:+f.get('font'),ageMode:f.get('ageMode'),hiddenOrder:f.get('hiddenOrder'),showShensha:f.has('showShensha'),hiddenShensha:SHENSHA_NAMES.filter(n=>!f.getAll('enabledShensha').includes(n)),hideRelations:RELATION_TYPES.filter(n=>!f.getAll('enabledRelation').includes(n))};if(!store(PREF,nextPrefs))return;prefs=nextPrefs;state.current=next;state.result=result;state.compare=state.compare?compare(next,state.partner):null;store(OPTIONS,next);mount();toast('规则与显示设置已保存，当前命盘已重算。');}catch(err){toast(err.message);}}

function render(){document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===state.tab));
 try{$('#content').innerHTML=({home:homeView,rules:rulesView,wealth:wealthView,multi:multiView,bazi:baziView,ziwei:ziweiView,qimen:qimenView,compare:compareView,wuyun:wuyunView,calendar:calendarView,reverse:reverseView,knowledge:knowledgeView,records:recordsView,reader:readerView}[state.tab])();}catch(err){$('#content').innerHTML=`<section class="card empty-state"><h2>当前配置未能生成此模块</h2><p>${esc(err.message)}</p><p>请检查日期和排盘设置。</p></section>`;}
 $('#partner-form')?.addEventListener('submit',e=>{e.preventDefault();try{const f=new FormData(e.target);state.partner={...state.current,name:String(f.get('name')),date:String(f.get('date')),time:String(f.get('time')),gender:+f.get('gender')};state.compare=compare(state.current,state.partner);render();}catch(err){toast(err.message);}});
 $('#feedback-note')?.addEventListener('input',e=>state.feedback=e.target.value);$('#commentary-note')?.addEventListener('input',e=>state.commentary=e.target.value);
 $('#rules-form')?.addEventListener('submit',saveRules);
 $('#chart-note')?.addEventListener('input',e=>state.note=e.target.value);$('#record-tags')?.addEventListener('input',e=>state.recordTags=e.target.value);
 $('#knowledge-query')?.addEventListener('input',e=>{state.query=e.target.value;$('#knowledge-results').innerHTML=knowledgeResults();});
 $('#knowledge-type')?.addEventListener('change',e=>{state.knowledgeType=e.target.value;$('#knowledge-results').innerHTML=knowledgeResults();});
 $('#archive-query')?.addEventListener('input',e=>{state.archiveQuery=e.target.value;$('#archive-results').innerHTML=archiveResults();});
 for(const id of ['flow-date','flow-time'])$('#'+id)?.addEventListener('change',e=>{const key=id==='flow-date'?'flowDate':'flowTime',prev=state[key];try{state[key]=e.target.value;validateInput({...state.current,date:state.flowDate,time:state.flowTime});render();}catch(err){state[key]=prev;toast(err.message);}});
 $('#wuyun-year')?.addEventListener('change',e=>{const year=+e.target.value;if(year>=1901&&year<=2099){state.wuyunYear=year;render();}else toast('年份须在 1901—2099 年。');});
 $('#reverse-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{state.reverseValues=[0,1,2,3].map(i=>String(f.get('p'+i)).trim());state.reverse=reversePillars(state.reverseValues,+f.get('start'),+f.get('end'),state.current.sect);$('#reverse-results').innerHTML=reverseResults();if(!state.reverse.length)toast('该范围内未找到匹配的代表时刻。');}catch(err){toast(err.message);}});
 $('#reader-page')?.addEventListener('change',e=>setReaderPage(+e.target.value-1));$('#reader-query')?.addEventListener('input',e=>state.readerQuery=e.target.value);
}
function dialog(html){$('#dialog-body').innerHTML=html;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function referenceHTML(v){if(typeof v!=='object'||v===null)return esc(v);if(Array.isArray(v))return v.map(referenceHTML).join('<br>');return Object.entries(v).map(([k,v])=>`<div class="reference-row"><b>${esc(k)}</b><div>${referenceHTML(v)}</div></div>`).join('');}
function showKnowledge(name,type){if(type==='术语'){const x=glossary.find(x=>x.term===name);dialog(`<small>八字术语 / 本地资料</small><h2>${esc(name)}</h2><div class="prose">${esc(x?.text||'暂无资料')}</div>`);}else{const x=stars.find(x=>x.name===name);dialog(`<small>紫微星曜 / 本地资料</small><h2>${esc(name)}</h2>${x?Object.entries(x).filter(([k])=>k!=='name').map(([k,v])=>`<section class="star-section"><h3>${esc(({basics:'基本属性',personality:'传统取象',strength:'庙旺落陷',transforms:'四化释义',career:'事业取象',relationships:'关系取象',combos:'组合释义'}[k])||k)}</h3><div class="prose">${referenceHTML(v)}</div></section>`).join(''):'<p>本地库暂无此星的详细条目。</p>'}`);}}
function about(){dialog(`<h2>星历 · 离线研习室 0.4.1</h2><p>本机重建的公共历法与传统排盘工具。</p><div class="scope-table"><div><b>八字</b><span>四柱细盘、藏干、十神、星运、自坐、纳音、空亡、40 类神煞规则、胎元胎息命身宫、120 年大运、小运、流年流月、流日流时、月令取格候选、干支关系和四柱反查；综合研习报告含旺衰双口径复核、格局组合、调候、喜忌候选、特殊格筛查、分主题解读、岁运同参与报告导出。</span></div><div><b>紫微</b><span>通行 / 中州安星，天 / 地 / 人盘，本命至流时运限、流耀、四化、宫干飞化、自化与三方四正。</span></div><div><b>其他</b><span>奇门拆补 / 置闰（符头法）/ 手动定局，显示超神、接气、正授、闰局、符头与定局对照；五运六气基础排布；万年历、黄历、时辰、节气；合盘对照；知识库；2—4盘对比、财星研习；分柱、人元司令、命宫中气口径；分类档案、反馈、点评、标签星标；文本书房、书签和系统朗读。</span></div><div><b>尚未实现</b><span>原服务器同款报告和最终喜用神、阴盘和命理奇门、时粒度叠局、十四日阈值置闰变体、完整特殊格与任意自编神煞算法、七政四余、真天体图、原版古籍全文、在线翻译与云同步。</span></div><div><b>精度与流派</b><span>时区使用标准 UTC 偏移，夏令时由用户指定。真太阳时含近似均时差。排盘规则采用 lunar-javascript、iztro、qimen-dunjia，未与原版全面逐盘比对。</span></div><div><b>资料与备份</b><span>3380 个境内地区坐标及 168 条术语、83 条星曜资料来源于用户提供的安装包。档案和书籍仅存本机；“研习档案 → 导出全部”包含书房，旧版备份仍可导入。</span></div></div>`);}
function preferences(){state.tab='rules';render();}
function lunarDialog(){const l=lunarDateOf(state.current.date);dialog(`<h2>农历输入</h2><form id="lunar-form"><div class="reverse-fields"><label>农历年<input name="year" type="number" min="1901" max="2099" value="${l.year}" required></label><label>月<input name="month" type="number" min="1" max="12" value="${l.month}" required></label><label>日<input name="day" type="number" min="1" max="30" value="${l.day}" required></label></div><label class="check"><input name="leap" type="checkbox" ${l.leap?'checked':''}>闰月</label><p class="fine">按中国农历转换为公历；出生时间与地区设置保留。</p><button class="primary" type="submit">转换并排盘</button></form>`);$('#lunar-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{const date=lunarToSolar(+f.get('year'),+f.get('month'),+f.get('day'),f.has('leap'));$('#detail-dialog').close();updateInput({...readForm($('#chart-form')),date});toast('已转换为公历 '+date);}catch(err){toast(err.message);}});}
function regionResults(){const q=state.regionQuery.trim();return regions.filter(r=>r.name.includes(q)).slice(0,60).map(r=>`<button class="region-result" data-region="${regions.indexOf(r)}"><b>${esc(r.name)}</b><span>经度 ${r.longitude}° · UTC${r.utcOffset>=0?'+':''}${r.utcOffset}</span></button>`).join('')||'<p>未找到地区，可在排盘设置中直接输入经度和时区。</p>';}
function regionDialog(){state.regionQuery='';dialog(`<h2>出生地区</h2><input id="region-query" type="search" placeholder="搜索省、市、区县或城市" aria-label="搜索地区"><p class="fine">境内坐标来自随包地区表（GCJ-02，作近似经度）；海外快捷项使用标准时区，夏令时需自行勾选。</p><div id="region-results">${regionResults()}</div>`);$('#region-query').addEventListener('input',e=>{state.regionQuery=e.target.value;$('#region-results').innerHTML=regionResults();});}
function recordCategory(){return ['qimen','ziwei','compare','wealth','multi'].includes(state.tab)?state.tab:state.baziMode==='reading'?'case':'bazi';}
function save(){if(state.tab==='multi'&&!state.multiInputs.length)return toast('先从档案中加入至少一份对照命盘。');if(state.tab==='compare'&&!state.compare)return toast('请先完成乙方对照排盘。');const previous=records,category=recordCategory(),old=records.find(r=>r.id===state.recordId),id=old&&(old.category||'bazi')===category?old.id:crypto.randomUUID(),record={id,input:{...state.current},pillars:state.result.pillars.map(p=>p.value),category,note:state.note,feedback:state.feedback,commentary:state.commentary,tags:state.recordTags,starred:old?.starred||false,context:{flowDate:state.flowDate,flowTime:state.flowTime,decade:state.decade,year:state.year,baziMode:state.baziMode,ziweiScope:state.ziweiScope,partner:state.tab==='compare'?state.partner:null,multiInputs:state.tab==='multi'?state.multiInputs:[]},updated:new Date().toISOString()};records=[record,...records.filter(r=>r.id!==id)];if(persist()){state.recordId=id;render();toast(`${CATEGORIES[category]}、反馈与点评已保存`);}else records=previous;}

function downloadText(text,filename,type='text/plain'){if(window.webkit?.messageHandlers?.export){window.webkit.messageHandlers.export.postMessage({text,filename});return;}const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('文件已生成');}
function downloadJSON(data,filename){downloadText(JSON.stringify(data,null,2),filename,'application/json');}
function exportRecords(){downloadJSON({format:'xinglu-archive',version:2,exported:new Date().toISOString(),records,books,prefs},`星历全部备份-${today.date}.json`);}
async function importRecords(e){const file=e.target.files[0];if(!file)return;try{if(file.size>12e6)throw new Error('备份文件须小于 12 MB。');const data=JSON.parse(await file.text());if(data.format!=='xinglu-archive'||![1,2].includes(data.version)||!Array.isArray(data.records)||data.records.length>2000)throw new Error('这不是支持的星历备份文件。');const incoming=data.records.map(r=>cleanRecord(r,defaults,crypto.randomUUID()));const incomingBooks=(Array.isArray(data.books)?data.books:[]).slice(0,100).map(b=>{if(typeof b.text!=='string'||b.text.length>2e6)throw new Error('备份中有超限书籍。');return {id:crypto.randomUUID(),title:String(b.title||'未命名').slice(0,120),text:b.text,page:Number.isInteger(b.page)?Math.max(0,b.page):0,bookmarks:(Array.isArray(b.bookmarks)?b.bookmarks:[]).filter(p=>Number.isInteger(p)&&p>=0).slice(0,1000)};});const incomingPrefs=data.prefs?cleanPreferences(data.prefs):prefs,nextRecords=[...incoming,...records],nextBooks=[...incomingBooks,...books],oldRecords=localStorage.getItem(KEY),oldBooks=localStorage.getItem(BOOKS),oldPrefs=localStorage.getItem(PREF);try{localStorage.setItem(KEY,JSON.stringify(nextRecords));localStorage.setItem(BOOKS,JSON.stringify(nextBooks));localStorage.setItem(PREF,JSON.stringify(incomingPrefs));}catch(err){if(oldRecords===null)localStorage.removeItem(KEY);else localStorage.setItem(KEY,oldRecords);if(oldBooks===null)localStorage.removeItem(BOOKS);else localStorage.setItem(BOOKS,oldBooks);if(oldPrefs===null)localStorage.removeItem(PREF);else localStorage.setItem(PREF,oldPrefs);throw new Error('存储空间不足，导入已撤回。');}records=nextRecords;books=nextBooks;prefs=incomingPrefs;applyPrefs();state.tab='records';render();toast(`已导入 ${incoming.length} 份档案、${incomingBooks.length} 本书籍，原资料保留。`);}catch(err){toast(`导入失败：${err.message}`);}e.target.value='';}
async function importBook(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('单本书籍最多 2 MB。');const text=await file.text();if(!text.trim())throw new Error('文本内容为空。');const book={id:crypto.randomUUID(),title:file.name.replace(/\.(txt|md)$/i,''),text,page:0,bookmarks:[]},next=[book,...books];if(store(BOOKS,next)){books=next;state.readerId=book.id;state.readerPage=0;render();}}catch(err){toast(err.message);}e.target.value='';}
function setReaderPage(page){const b=books.find(b=>b.id===state.readerId);if(!b)return;page=Math.max(0,Math.min(bookPages(b).length-1,page));b.page=state.readerPage=page;store(BOOKS,books);render();}
function readAloud(){const b=books.find(b=>b.id===state.readerId);if(!b)return;const text=bookPages(b)[state.readerPage];if(window.webkit?.messageHandlers?.speak){window.webkit.messageHandlers.speak.postMessage({text});return;}if(!('speechSynthesis'in window))return toast('当前环境未提供系统朗读。');const voice=speechSynthesis.getVoices().find(v=>v.localService&&v.lang.startsWith('zh'));if(!voice)return toast('没有可用的本机中文语音，请先在系统安装中文语音。');speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang='zh-CN';u.rate=.9;speechSynthesis.speak(u);}
function stopReading(){window.webkit?.messageHandlers?.speak?.postMessage({stop:true});window.speechSynthesis?.cancel();}
function showPalace(index){const z=getZiwei(),p=z.palaces[index];dialog(`<small>${esc(p.heavenlyStem+p.earthlyBranch)} / ${p.decadal.range.join('—')} 岁</small><h2>${esc(p.name)}${p.isBodyPalace?' · 身宫':''}</h2><div class="star-chips">${[...p.majorStars,...p.minorStars,...p.adjectiveStars].map(s=>`<button class="secondary" data-knowledge="${esc(s.name)}" data-kind="星曜">${esc(s.name)} ${esc(s.brightness||'')}${s.mutagen?' 化'+esc(s.mutagen):''}</button>`).join('')}</div><dl class="data-list"><dt>长生</dt><dd>${p.changsheng12}</dd><dt>博士</dt><dd>${p.boshi12}</dd><dt>将前</dt><dd>${p.jiangqian12}</dd><dt>岁前</dt><dd>${p.suiqian12}</dd></dl><p>点击星曜读取本地详细资料。</p>`);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;try{
 if(d.category){state.archiveCategory=d.category;render();}
 if(d.tab){stopReading();state.tab=d.tab;render();window.scrollTo(0,0);}
 if(d.qimenMethod){const next={...readForm($('#chart-form')),qimenMethod:d.qimenMethod};state.result=calculate(next);state.current=next;store(OPTIONS,next);mount();}
 if(d.baziMode){state.baziMode=d.baziMode;render();}if(d.scope){state.ziweiScope=d.scope;render();}
 if(d.decade!==undefined){state.decade=+d.decade;state.year=0;render();}if(d.year!==undefined){state.year=+d.year;render();}
 if(d.flowMonth!==undefined){const term=solarTerms(+d.flowYear).filter(t=>['立春','惊蛰','清明','立夏','芒种','小暑','立秋','白露','寒露','立冬','大雪'].includes(t.name))[+d.flowMonth];const baseDate=term?new Date(term.date.replace(' ','T')+'+08:00'):new Date(`${+d.flowYear+1}-01-10T12:00:00+08:00`);const local=new Date(baseDate.getTime()+(36+Number(state.current.utcOffset??8)+(state.current.dst?1:0))*3600000);const date=local.toISOString().slice(0,10);if(+date.slice(0,4)>2099)throw new Error('该流月超出当前 1901—2099 年范围。');state.flowDate=date;state.flowTime=local.toISOString().slice(11,16);state.baziMode='flow';render();}
 if(d.shift)updateInput(shiftInput(readForm($('#chart-form')),+d.shift));
 if(d.palace!==undefined){state.palace=+d.palace;render();}if(d.palaceDetail!==undefined)showPalace(+d.palaceDetail);
 if(d.ziweiYear&&(+d.ziweiYear<1901||+d.ziweiYear>2099))throw new Error('该大限超出当前 1901—2099 年范围。');
 if(d.ziweiYear){state.flowDate=`${d.ziweiYear}-07-01`;state.ziweiScope='decadal';render();}
 if(d.shensha){const list=[...state.result.shensha,...getFlow().shensha,...fortuneShensha(state.result,state.decade,shensha).hits].filter(h=>h.name===d.shensha);dialog(`<h2>${esc(d.shensha)}</h2><p>命中条件：</p><div class="prose">${[...new Set(list.map(h=>h.evidence))].map(esc).join('\n')}</div><p class="fine">按所标注的年 / 日干支、月令、纳音或性别口径匹配。德秀仅列结构候选，天罗地网为互见简法。这里只显示组合与查法，不推断应验事件。</p>`);}
 if(d.qimen!==undefined){const {chart:c,patterns}=qimen(state.current),i=+d.qimen;dialog(`<h2>${esc(c.方位[i])}宫</h2><p>天盘 ${esc(c.天盤[i])} · 地盘 ${esc(c.地盤[i])}<br>八门 ${esc(c.天門[i]||'中宫无门')} · 九星 ${esc(c.九星[i])}<br>八神 ${esc(c.八神[i]||'中宫无神')}</p><div class="prose">${esc(patterns.filter(p=>p.宮===c.方位[i]).map(p=>`${p.格}：${p.細節}`).join('\n\n')||'未标记此宫专属格局。')}</div>`);}
 if(d.knowledge)showKnowledge(d.knowledge,d.kind);
 if(d.calDate){state.calendarDate=d.calDate;render();}if(d.calMonth){const x=new Date(state.calendarDate+'T12:00:00Z');x.setUTCDate(1);x.setUTCMonth(x.getUTCMonth()+ +d.calMonth);const date=x.toISOString().slice(0,10);if(+date.slice(0,4)>=1901&&+date.slice(0,4)<=2099){state.calendarDate=date;render();}}
 if(d.useDate){state.tab='bazi';updateInput({...state.current,date:d.useDate});}
 if(d.wuyunStep){state.wuyunYear=Math.max(1901,Math.min(2099,state.wuyunYear+ +d.wuyunStep));render();}
 if(d.reverseDate){state.tab='bazi';updateInput({...state.current,date:d.reverseDate,time:d.reverseTime,yearBoundary:'exact',utcOffset:8,dst:false,trueSolar:false});}
 if(d.open){const r=records.find(r=>r.id===d.open);if(r){state.current={...defaults,...r.input};state.result=calculate(state.current);state.recordId=r.id;state.note=r.note||'';state.feedback=r.feedback||'';state.commentary=r.commentary||'';state.recordTags=r.tags||'';const c=r.context||{};state.tab=['qimen','ziwei','compare','wealth','multi'].includes(r.category)?r.category:'bazi';state.decade=c.decade??1;state.year=c.year??0;state.baziMode=r.category==='case'?'reading':c.baziMode||'professional';state.flowDate=c.flowDate||today.date;state.flowTime=c.flowTime||'12:00';state.ziweiScope=c.ziweiScope||'origin';state.multiInputs=c.multiInputs||[];state.compare=null;if(c.partner){state.partner=c.partner;state.compare=compare(state.current,state.partner);}store(OPTIONS,state.current);mount();}}
 if(d.multiAdd){const r=records.find(r=>r.id===d.multiAdd);if(!r)throw new Error('档案不存在。');if(state.multiInputs.length>=3)throw new Error('最多四盘（当前盘加三份档案）。');if(JSON.stringify(r.input)===JSON.stringify(state.current)||state.multiInputs.some(i=>JSON.stringify(i)===JSON.stringify(r.input)))throw new Error('这份命盘已经在对比中。');state.multiInputs.push({...defaults,...r.input});state.tab='multi';render();window.scrollTo(0,0);}
 if(d.multiRemove!==undefined){state.multiInputs.splice(+d.multiRemove,1);render();}

 if(d.recordCompare){const r=records.find(r=>r.id===d.recordCompare);state.partner={...defaults,...r.input};state.compare=compare(state.current,state.partner);state.tab='compare';render();window.scrollTo(0,0);}
 if(d.star){const r=records.find(r=>r.id===d.star);const old=r.starred;r.starred=!r.starred;if(!persist())r.starred=old;$('#archive-results').innerHTML=archiveResults();}
 if(d.delete&&confirm('删除这份本地档案？')){const prev=records;records=records.filter(r=>r.id!==d.delete);if(persist()){if(state.recordId===d.delete)state.recordId=null;render();}else records=prev;}
 if(d.book){state.readerId=d.book;state.readerPage=books.find(b=>b.id===d.book)?.page||0;render();}
 if(d.readerStep)setReaderPage(state.readerPage+ +d.readerStep);if(d.readerPage!==undefined)setReaderPage(+d.readerPage);
 const a=d.action;
 if(a==='edit-input')$('#input-dialog').showModal();if(a==='close-input')$('#input-dialog').close();
 if(a==='case'){state.tab='bazi';state.baziMode='reading';render();window.scrollTo(0,0);}
 if(a==='minute-detail')dialog(`<h2>分柱 · 时上五鼠遁</h2><p>${esc(state.result.minutePillar?.evidence||'请先在规则中开启分柱。')}</p><p>从所选钟时的时辰起点开始，每10分钟换一支，以时干代替日干按五鼠遁起干；区间左闭右开，如起点至不足10分钟为子段。23点起子时，00点在同一时辰的第7段。</p><p class="fine">公开依据：《新玄機》176期，伍立群《分柱程式之我見》（2012年2月）。第五柱独立列示，不加入原有四柱旺衰与格局计算。</p>`);
 if(a==='commander-detail')dialog(`<h2>人元司令 · ${state.result.commander.method}</h2><p>${state.result.commander.term} ${state.result.commander.start}（UTC+8）起算，已过 ${state.result.commander.elapsed.toFixed(4)} 日，当前为${state.result.commander.stem}。</p><p>${state.result.commander.table.map(([g,n])=>g+' '+n+'日').join(' → ')}</p><p class="fine">满分日数后换下一段；末段延续到下一节。公开依据：琴鹤堂国学《八字月令人元司令分野及乘气用法详解》（2023-05-31）。不把司令换算为五行分数。</p>`);
 if(a==='enable-shensha'||a==='disable-shensha'){document.querySelectorAll('#rules-form input[name="enabledShensha"]').forEach(el=>el.checked=a==='enable-shensha');}

 if(a==='save')save();if(a==='about')about();if(a==='preferences')preferences();if(a==='close-dialog')$('#detail-dialog').close();if(a==='lunar')lunarDialog();if(a==='regions')regionDialog();
 if(d.region!==undefined){const r=regions[+d.region],input=readForm($('#chart-form'));$('#detail-dialog').close();updateInput({...input,place:r.name,longitude:r.longitude,utcOffset:r.utcOffset});}
 if(a==='now')updateInput(nowInput(readForm($('#chart-form'))));
 if(a==='flow-now'){const n=nowInput(state.current);state.flowDate=n.date;state.flowTime=n.time;render();}
 if(a==='calendar-today'){state.calendarDate=nowInput(defaults).date;render();}
 if(a==='only-star'){state.onlyStar=!state.onlyStar;render();}
 if(a==='export-reading')downloadText(readingMarkdown(getReading()),`星历综合解读-${state.current.date}.md`,'text/markdown');
 if(a==='export')exportRecords();if(a==='import')$('#import-file').click();
 if(a==='print'){if(window.webkit?.messageHandlers?.print)window.webkit.messageHandlers.print.postMessage({});else window.print();}
 if(a==='import-book')$('#book-file').click();if(a==='reader-back'){stopReading();state.readerId=null;render();}
 if(a==='bookmark'){const b=books.find(b=>b.id===state.readerId);b.bookmarks=b.bookmarks||[];b.bookmarks=b.bookmarks.includes(state.readerPage)?b.bookmarks.filter(p=>p!==state.readerPage):[...b.bookmarks,state.readerPage].sort((a,b)=>a-b);store(BOOKS,books);render();}
 if(a==='read-aloud')readAloud();if(a==='stop-reading')stopReading();
 if(a==='reader-search'){const b=books.find(b=>b.id===state.readerId),q=state.readerQuery;if(!q)return;const pages=bookPages(b);let p=pages.findIndex((s,i)=>i>state.readerPage&&s.includes(q));if(p<0)p=pages.findIndex(s=>s.includes(q));if(p>=0)setReaderPage(p);else toast('本书未找到该文字。');}
}catch(err){toast(err.message);}});
mount();
if(location.protocol.startsWith('http')&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineLabel='网页离线缓存就绪';$('#offline-status').textContent=offlineLabel;}).catch(()=>{$('#offline-status').textContent='网页缓存不可用';});
